const byValueThenPos = (a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : a[1] - b[1]);

class Table {
  constructor(rows = []) {
    this.rows = [];
    this.indexes = {};
    for (const r of rows) this.insert(r);
  }

  insert(row) {
    const pos = this.rows.length;
    this.rows.push(row);
    for (const column of Object.keys(this.indexes)) {
      const idx = this.indexes[column];
      // equal values go after existing ones, which keeps insertion order for ties
      const at = this.upperBound(idx, row[column], { n: 0 });
      idx.splice(at, 0, [row[column], pos]);
    }
  }

  createIndex(column) {
    this.indexes[column] = this.rows.map((r, pos) => [r[column], pos]).sort(byValueThenPos);
  }

  // first index position whose value is >= v
  lowerBound(idx, v, count) {
    let lo = 0, hi = idx.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      count.n++;
      if (idx[mid][0] < v) lo = mid + 1; else hi = mid;
    }
    return lo;
  }

  // first index position whose value is > v
  upperBound(idx, v, count) {
    let lo = 0, hi = idx.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      count.n++;
      if (idx[mid][0] <= v) lo = mid + 1; else hi = mid;
    }
    return lo;
  }

  findRange(column, lo, hi) {
    const idx = this.indexes[column];
    if (!idx) {
      const matches = [];
      this.rows.forEach((r, pos) => {
        if (r[column] >= lo && r[column] <= hi) matches.push([r[column], pos]);
      });
      matches.sort(byValueThenPos);
      return { rows: matches.map(([, pos]) => this.rows[pos]), plan: 'scan', touched: this.rows.length, comparisons: this.rows.length };
    }
    const count = { n: 0 };
    const start = this.lowerBound(idx, lo, count);
    const end = this.upperBound(idx, hi, count);
    const rows = idx.slice(start, end).map(([, pos]) => this.rows[pos]);
    return { rows, plan: 'index', touched: rows.length, comparisons: count.n };
  }

  findEqual(column, value) {
    return this.findRange(column, value, value);
  }
}

