// 1,000 reading sessions spread over 50 classes; scores 0..99
const make = (n, classes = 50) => Array.from({ length: n }, (_, i) => ({ id: i + 1, studentId: 'st' + (i % 400), classId: 'c' + (i * 7 % classes), score: (i * 37) % 100, minutes: 5 + (i % 30) }));
const t = new Table(make(1000));
const r = t.findEqual('classId', 'c7');
assertEqual(r.plan, 'scan');
assertEqual(r.touched, 1000);
assertEqual(r.rows.length, 20);
assert(r.rows.every(x => x.classId === 'c7'), 'every row should be in class c7');

// 1,000 reading sessions spread over 50 classes; scores 0..99
const make = (n, classes = 50) => Array.from({ length: n }, (_, i) => ({ id: i + 1, studentId: 'st' + (i % 400), classId: 'c' + (i * 7 % classes), score: (i * 37) % 100, minutes: 5 + (i % 30) }));
const t = new Table(make(1000));
const before = t.findEqual('classId', 'c7').rows.map(r => r.id);
t.createIndex('classId');
const r = t.findEqual('classId', 'c7');
assertEqual(r.plan, 'index');
assertEqual(r.rows.map(x => x.id), before, 'same rows in the same order');
assertEqual(r.touched, 20);

// 1,000 reading sessions spread over 50 classes; scores 0..99
const make = (n, classes = 50) => Array.from({ length: n }, (_, i) => ({ id: i + 1, studentId: 'st' + (i % 400), classId: 'c' + (i * 7 % classes), score: (i * 37) % 100, minutes: 5 + (i % 30) }));
const t = new Table(make(100000, 5000));
t.createIndex('classId');
const r = t.findEqual('classId', 'c123');
assertEqual(r.rows.length, 20);
assert(r.comparisons > 0 && r.comparisons <= 40, 'expected at most 40 comparisons (two binary searches of ~17 steps), got ' + r.comparisons);

// 1,000 reading sessions spread over 50 classes; scores 0..99
const make = (n, classes = 50) => Array.from({ length: n }, (_, i) => ({ id: i + 1, studentId: 'st' + (i % 400), classId: 'c' + (i * 7 % classes), score: (i * 37) % 100, minutes: 5 + (i % 30) }));
const t = new Table(make(1000));
t.createIndex('score');
const r = t.findRange('score', 70, 72);
assertEqual(r.plan, 'index');
assertEqual(r.rows.length, 30);
assertEqual(r.touched, 30);
assertEqual(r.rows.map(x => x.score), [...Array(10).fill(70), ...Array(10).fill(71), ...Array(10).fill(72)], 'ordered by score');
const ids70 = r.rows.filter(x => x.score === 70).map(x => x.id);
assertEqual(ids70, [...ids70].sort((a, b) => a - b), 'ties keep insertion order');

