const r = t.findEqual('classId', 'c7');
assertEqual(r.rows.length, 21);
assertEqual(r.rows[r.rows.length - 1].id, 5001, 'new row comes last among equals');
assertEqual(t.findEqual('classId', 'c999').rows.map(x => x.id), [5002]);

